        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = 'eb0962a0-8b05-4a37-b1cc-05439d7a18bc'
        AND charge_id = 654612;
   
    RETURN;
END IF;

END IF;

